def _get_run_length_boundaries(columns_values: list[list]) -> list[int]:
    """Compute the start indices of consecutive runs sharing the same values across all columns.

    Args:
        columns_values (`list[list]`): One list of values per grouping column, all of the same length.

    Returns:
        `list[int]`: The start index of each run, always starting with `0` (empty if there are no rows).
    """
    num_rows = len(columns_values[0]) if columns_values else 0
    if num_rows == 0:
        return []
    boundaries = [0]
    for i in range(1, num_rows):
        if any(values[i] != values[i - 1] for values in columns_values):
            boundaries.append(i)
    return boundaries


